<script>
document.getElementById('mcn-tool-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('triggerBtn'),text=document.getElementById('btnText'),icon=document.getElementById('btnIcon'),spinner=document.getElementById('btnSpinner'),message=document.getElementById('statusMessage'),payload={automation_type:document.getElementById('automationType').value,sheet_url:document.getElementById('sheetUrl').value,sheet_name:document.getElementById('sheetName').value,header_row:document.getElementById('headerRow').value,first_data_row:document.getElementById('firstDataRow').value,limit:document.getElementById('limitData').value,template_content:document.getElementById('templateContent').value};if(!payload.sheet_url.includes('docs.google.com/spreadsheets')||!payload.sheet_name.trim()){message.textContent='Isi link Google Sheet dan nama sheet dengan benar.';message.className='mt-5 rounded-xl bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-700';return}button.disabled=true;text.textContent='Memproses...';icon.classList.add('hidden');spinner.classList.remove('hidden');message.classList.add('hidden');try{const response=await fetch(@json(route('n8n.trigger')),{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify(payload)}),result=await response.json().catch(()=>({}));message.textContent=result.message||(response.ok?'Integrasi berhasil dijalankan.':'Integrasi gagal dijalankan.');message.className=`mt-5 rounded-xl px-4 py-3 text-sm font-semibold ${response.ok?'bg-emerald-50 text-emerald-700':'bg-rose-50 text-rose-700'}`;if(response.ok){document.getElementById('sheetUrl').value='';document.getElementById('sheetName').value=''}}catch(error){message.textContent='Tidak dapat menghubungi server integrasi.';message.className='mt-5 rounded-xl bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-700'}finally{button.disabled=false;text.textContent='Jalankan Integrasi';icon.classList.remove('hidden');spinner.classList.add('hidden')}});
</script>
